              "code_example": "import { useState } from \"react\";\n\nexport function TwoCounters() {\n  return (\n    <section>\n      <Counter label=\"A\" />\n      <hr />\n      <ReadOnly label=\"B\" />\n    </section>\n  );\n}\n\nfunction Counter({ label }: { label: string }) {\n  const [count, setCount] = useState(0);\n  return (\n    <button onClick={() => setCount((c) => c + 1)} type=\"button\">\n      {label}: {count}\n    </button>\n  );\n}\n\nfunction ReadOnly({ label }: { label: string }) {\n  return <p>Static: {label}</p>;\n}",
