              "code_example": "import { useRef, useState } from \"react\";\nimport Popper from \"@mui/material/Popper\";\nimport Box from \"@mui/material/Box\";\n\nexport default function HoverHint() {\n  const [anchor, setAnchor] = useState<HTMLElement | null>(null);\n  return (\n    <>\n      <button\n        ref={useRef(null)}\n        onMouseEnter={(event) => {\n          setAnchor(event.currentTarget);\n        }}\n        onMouseLeave={() => {\n          setAnchor(null);\n        }}\n      >\n        Hover me\n      </button>\n      <Popper open={Boolean(anchor)} anchorEl={anchor} placement=\"top\">\n        <Box sx={{ p: 1, bgcolor: \"background.paper\", boxShadow: 3 }}>\n          Floating hint\n        </Box>\n      </Popper>\n    </>\n  );\n}",
