              "code_example": "import { useMutation, useQueryClient } from \"@tanstack/react-query\";\n\ninterface Post { id: number; title: string; }\n\nasync function updatePost(id: number, patch: Partial<Post>): Promise<Post> {\n  const res = await fetch(`/api/posts/${id}`, {\n    method: \"PATCH\",\n    headers: { \"Content-Type\": \"application/json\" },\n    body: JSON.stringify(patch),\n  });\n  if (!res.ok) throw new Error(`HTTP ${res.status}`);\n  return res.json();\n}\n\nexport function PostEditor({ post }: { post: Post }): React.ReactElement {\n  const queryClient = useQueryClient();\n\n  const save = useMutation({\n    mutationFn: (patch: Partial<Post>) => updatePost(post.id, patch),\n    onSuccess: () => {\n      void queryClient.invalidateQueries({ queryKey: [\"posts\"] });\n      void queryClient.invalidateQueries({ queryKey: [\"post\", post.id] });\n    },\n  });\n\n  return (\n    <button onClick={() => save.mutate({ title: \"Updated\" })} disabled={save.isPending}>\n      {save.isPending ? \"Saving…\" : \"Save\"}\n    </button>\n  );\n}",
