              "code_example": "import { useQuery } from \"@tanstack/react-query\";\nimport type { ReactElement } from \"react\";\n\ninterface Todo { readonly id: number; readonly title: string; }\nconst placeholderTodos: ReadonlyArray<Todo> = [\n  { id: 0, title: \"Loading…\" },\n];\n\nexport function Todos(): ReactElement {\n  const { data, isPlaceholderData } = useQuery({\n    queryKey: [\"todos\"] as const,\n    queryFn: ({ signal }) => fetch(\"/api/todos\", { signal }).then((r) => r.json() as Promise<Todo[]>),\n    placeholderData: placeholderTodos,\n  });\n\n  return (\n    <ul style={{ opacity: isPlaceholderData ? 0.6 : 1 }}>\n      {data.map((t) => <li key={t.id}>{t.title}</li>)}\n    </ul>\n  );\n}",
