              "code_example": "// pages/posts.tsx\nimport {\n  HydrationBoundary,\n  QueryClient,\n  dehydrate,\n  queryOptions,\n  useQuery,\n} from \"@tanstack/react-query\";\nimport type { DehydratedState } from \"@tanstack/react-query\";\nimport type { ReactElement } from \"react\";\n\nexport interface Post {\n  readonly id: number;\n  readonly title: string;\n}\n\nasync function getPosts(): Promise<ReadonlyArray<Post>> {\n  const response = await fetch(\"https://example.test/api/posts\");\n  if (!response.ok) throw new Error(`Posts request failed: ${response.status}`);\n  return (await response.json()) as ReadonlyArray<Post>;\n}\n\nexport const postsQueryOptions = () =>\n  queryOptions({\n    queryKey: [\"posts\"] as const,\n    queryFn: getPosts,\n  });\n\nexport async function getServerSideProps(): Promise<{\n  props: { dehydratedState: DehydratedState };\n}> {\n  const queryClient = new QueryClient();\n  await queryClient.prefetchQuery(postsQueryOptions());\n  return { props: { dehydratedState: dehydrate(queryClient) } };\n}\n\nfunction Posts(): ReactElement {\n  // No loading state on first paint: the cache already holds this entry.\n  const { data, status } = useQuery(postsQueryOptions());\n\n  if (status === \"pending\") return <p>Loading posts…</p>;\n  if (status === \"error\") return <p role=\"alert\">Could not load posts.</p>;\n\n  return (\n    <ul>\n      {data.map((post) => (\n        <li key={post.id}>{post.title}</li>\n      ))}\n    </ul>\n  );\n}\n\nexport default function PostsRoute({\n  dehydratedState,\n}: {\n  dehydratedState: DehydratedState;\n}): ReactElement {\n  return (\n    <HydrationBoundary state={dehydratedState}>\n      <Posts />\n    </HydrationBoundary>\n  );\n}",
